sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // 1. Block past Start Dates on new records
    if (current.isNewRecord() && !current.start_date.nil()) {
        var startDate = new GlideDate();
        startDate.setValue(current.start_date);
        var today = new GlideDate();

        if (startDate.before(today)) {
            gs.addErrorMessage('Start Date cannot be in the past.');
            current.setAbortAction(true);
            return;
        }
    }

    // 2. Require Assigned To & Shipping Address on Critical priority requests
    var prio = current.priority.toString().toLowerCase();
    if (prio == '1' || prio == 'critical') {
        if (current.assigned_to.nil() || current.shipping_address.nil()) {
            gs.addErrorMessage('Critical priority requests require both an Assigned To agent and a Shipping Address before saving.');
            current.setAbortAction(true);
            return;
        }
    }
})(current, previous);
